def pbAnnotate(annot)
  Settings::MAX_PARTY_SIZE.times do |i|
    @sprites["pokemon#{i}"].text = (annot) ? annot[i] : nil
  end
end

def pbSelect(item)
  @activecmd = item
  numsprites = Settings::MAX_PARTY_SIZE + ((@multiselect) ? 2 : 1)
  numsprites.times do |i|
    @sprites["pokemon#{i}"].selected = (i == @activecmd)
  end
end

def item
  return GameData::Item.try_get(@item)
end

def item_id
  return @item
end

# Gives an item to this Pokémon to hold.
# @param value [Symbol, String, GameData::Item, nil] ID of the item to give
#   to this Pokémon
def item=(value)
  return if value && !GameData::Item.exists?(value)
  @item = (value) ? GameData::Item.get(value).id : value
end
